    onSuccess: (_, r) => setTargets((t) => ({ ...t, [r.id]: '' })),
    onSettled: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });

  // A claim's amount changed on its row: saved as the claim's editor would save it, keeping its date, note and
