    public int batch(String sheetId, List<Long> claimIds) {
        jdbc.update("UPDATE sheet SET last_batch = COALESCE(last_batch, 0) + 1 WHERE id = ?", sheetId);
        int batch = lastBatch(sheetId);
        for (Long cid : claimIds) {
