        if (claim == null) return;
        jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, on_date, due)"
                + " SELECT ?, ?, ?, ?, today, ? FROM sheet WHERE id = ?",
                sheetId, claimId, claim.status(), by, dueNow(sheetId, claim), sheetId);
